40	 */
41	export interface ReadFileToolParams {
42	  /**
43	   * The path to the file to read
44	   */
45	  file_path: string;
46	
47	  /**
48	   * The line number to start reading from (optional, 1-based)
49	   */
50	  start_line?: number;
51	
52	  /**
53	   * The line number to end reading at (optional, 1-based, inclusive)
54	   */
55	  end_line?: number;
56	}
