58	class ReadFileToolInvocation extends BaseToolInvocation<
59	  ReadFileToolParams,
60	  ToolResult
61	> {
62	  private readonly resolvedPath: string;
63	  constructor(
64	    private config: Config,
65	    params: ReadFileToolParams,
66	    messageBus: MessageBus,
67	    _toolName?: string,
68	    _toolDisplayName?: string,
69	  ) {
70	    super(params, messageBus, _toolName, _toolDisplayName);
71	    this.resolvedPath = path.resolve(
72	      this.config.getTargetDir(),
73	      this.params.file_path,
74	    );
75	  }
76	
77	  getDescription(): string {
78	    const relativePath = makeRelative(
79	      this.resolvedPath,
80	      this.config.getTargetDir(),
81	    );
82	    return shortenPath(relativePath);
83	  }
84	
85	  override toolLocations(): ToolLocation[] {
86	    return [
87	      {
88	        path: this.resolvedPath,
89	        line: this.params.start_line,
90	      },
91	    ];
92	  }
93	
94	  override getPolicyUpdateOptions(
95	    _outcome: ToolConfirmationOutcome,
96	  ): PolicyUpdateOptions | undefined {
97	    return {
98	      argsPattern: buildFilePathArgsPattern(this.params.file_path),
99	    };
100	  }
101	
102	  async execute(): Promise<ToolResult> {
103	    const validationError = this.config.validatePathAccess(
104	      this.resolvedPath,
105	      'read',
106	    );
107	    if (validationError) {
108	      return {
109	        llmContent: validationError,
110	        returnDisplay: 'Path not in workspace.',
111	        error: {
112	          message: validationError,
113	          type: ToolErrorType.PATH_NOT_IN_WORKSPACE,
114	        },
115	      };
116	    }
117	
118	    const result = await processSingleFileContent(
119	      this.resolvedPath,
120	      this.config.getTargetDir(),
121	      this.config.getFileSystemService(),
122	      this.params.start_line,
123	      this.params.end_line,
124	    );
125	
126	    if (result.error) {
127	      return {
128	        llmContent: result.llmContent,
129	        returnDisplay: result.returnDisplay || 'Error reading file',
130	        error: {
131	          message: result.error,
132	          type: result.errorType,
133	        },
134	      };
135	    }
136	
137	    let llmContent: PartUnion;
138	    if (result.isTruncated) {
139	      const [start, end] = result.linesShown!;
140	      const total = result.originalLineCount!;
141	
142	      llmContent = `
143	IMPORTANT: The file content has been truncated.
144	Status: Showing lines ${start}-${end} of ${total} total lines.
145	Action: To read more of the file, you can use the 'start_line' and 'end_line' parameters in a subsequent 'read_file' call. For example, to read the next section of the file, use start_line: ${end + 1}.
146	
147	--- FILE CONTENT (truncated) ---
148	${result.llmContent}`;
149	    } else {
150	      llmContent = result.llmContent || '';
151	    }
152	
153	    const lines =
154	      typeof result.llmContent === 'string'
155	        ? result.llmContent.split('\n').length
156	        : undefined;
157	    const mimetype = getSpecificMimeType(this.resolvedPath);
158	    const programming_language = getProgrammingLanguage({
159	      file_path: this.resolvedPath,
160	    });
161	    logFileOperation(
162	      this.config,
163	      new FileOperationEvent(
164	        READ_FILE_TOOL_NAME,
165	        FileOperation.READ,
166	        lines,
167	        mimetype,
168	        path.extname(this.resolvedPath),
169	        programming_language,
170	      ),
171	    );
172	
173	    return {
174	      llmContent,
175	      returnDisplay: result.returnDisplay || '',
176	    };
177	  }
178	}
