import type { Config } from '../config/config.js';

export const JIT_CONTEXT_PREFIX =
  '\n\n--- Newly Discovered Project Context ---\n';
export const JIT_CONTEXT_SUFFIX = '\n--- End Project Context ---';

/**
 * Discovers just-in-time (JIT) project-level context for a given accessed path.
 *
 * Returns an empty string if JIT context is disabled, no context manager is
 * available, nothing is found, or an error occurs during discovery.
 */
export async function discoverJitContext(
  config: Config,
  accessedPath: string,
): Promise<string> {
  try {
    if (!config.isJitContextEnabled()) {
      return '';
    }

    const contextManager = config.getContextManager();
    if (!contextManager) {
      return '';
    }

    const workspaceDirectories = [
      ...config.getWorkspaceContext().getDirectories(),
    ];
    const jitContext = await contextManager.discoverContext(
      accessedPath,
      workspaceDirectories,
    );
    return jitContext || '';
  } catch {
    return '';
  }
}

/**
 * Appends discovered JIT context to the provided content, wrapping it with the
 * JIT context prefix and suffix. Returns the original content unchanged when
 * there is no JIT context to append.
 */
export function appendJitContext(
  llmContent: string,
  jitContext: string,
): string {
  if (!jitContext) {
    return llmContent;
  }
  return `${llmContent}${JIT_CONTEXT_PREFIX}${jitContext}${JIT_CONTEXT_SUFFIX}`;
}
